const c=id=>document.getElementById(id);
let careerState={email:'',name:'',role:'user'};
async function careerApi(path,options={}){const response=await fetch(path,{cache:'no-store',...options});const body=await response.json();if(!response.ok){const error=Error(body.error||'Request failed.');error.status=response.status;throw error;}return body;}
function careerMessage(text){c('career-message').textContent=text||'';}
function showCareerPanel(name){document.querySelectorAll('.career-panel').forEach(panel=>panel.hidden=panel.id!==`career-panel-${name}`);document.querySelectorAll('.career-tabs [role=tab]').forEach(tab=>tab.setAttribute('aria-selected',String(tab.dataset.careerPanel===name)));}
function renderCareerProfile(){const display=careerState.name||'CareerNaviq User';c('career-chip-name').textContent=display;c('career-chip-email').textContent=careerState.email||'';c('career-name').value=careerState.name||'';c('career-email').value=careerState.email||'';const greeting=document.getElementById('profile-greeting');if(greeting){greeting.textContent=`Hello, ${display.split(/\s+/)[0]}`;greeting.hidden=false;}}
function renderNotifications(){const items=[['Welcome','Your CareerNaviq account is ready. Complete your user profile first.'],['Tip','Use My List in Employer and Recruiter Directory to save records you contact often.'],['AI Auto Apply','Add resumes and application details before using AI Auto Apply.']];c('career-notifications').innerHTML=items.map(([title,text])=>`<article><strong>${title}</strong><span>${text}</span></article>`).join('');}
async function loadCareer(){try{const session=await careerApi('/api/session');if(session.status!=='approved'){location.replace('/');return;}careerState={email:session.email||'',name:session.name||'',role:session.role||'user'};document.body.classList.add('has-access');c('career-page').hidden=false;c('career-role').textContent=session.role==='admin'?'Admin':session.role==='coadmin'?'Coadmin':'User';renderCareerProfile();renderNotifications();careerMessage('');}catch(error){if(error.status===403)location.replace('/');else careerMessage(error.message);}}
document.querySelectorAll('.career-tabs [role=tab]').forEach(button=>button.addEventListener('click',()=>showCareerPanel(button.dataset.careerPanel)));
c('career-logout').addEventListener('click',async()=>{await careerApi('/api/logout',{method:'POST'});location.replace('/');});
c('career-user-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('[type=submit]');button.disabled=true;careerMessage('Saving user profile…');try{const result=await careerApi('/api/app-profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:c('career-name').value.trim()})});careerState.name=result.name||'';renderCareerProfile();careerMessage('User profile saved.');window.showAppNotice?.('User profile saved.');}catch(error){careerMessage(error.message);}finally{button.disabled=false;}});
c('career-question-form').addEventListener('submit',event=>{event.preventDefault();const question=c('career-question').value.trim();if(!question){careerMessage('Enter your question first.');return;}c('career-question').value='';careerMessage('Question saved. Admin question tracking will be connected next.');window.showAppNotice?.('Question saved.');});
loadCareer();
